const gl = $('Get Lesson').first().json || {};
const rp = $input.first().json || {};
const msg = (($('Webhook In').first().json.body || {}).message) || '';
const wantEmail = /\u05de\u05d9\u05d9\u05dc|\u05d0\u05d9\u05de\u05d9\u05d9\u05dc|email/i.test(msg);
if (!gl.has_lesson) {
  return [{ json: { answer: '\u05e2\u05d3\u05d9\u05d9\u05df \u05d0\u05d9\u05df \u05de\u05e2\u05e8\u05da \u05e9\u05d9\u05e2\u05d5\u05e8 \u05de\u05d5\u05db\u05df \u05dc\u05d4\u05d5\u05e8\u05d3\u05d4. \u05e0\u05e9\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e7\u05d5\u05d3\u05dd, \u05d5\u05d0\u05d6 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e4\u05d9\u05e7 PDF.' } }];
}
if (rp && rp.download_url) {
  let ans = '\u05de\u05e2\u05e8\u05da \u05d4\u05e9\u05d9\u05e2\u05d5\u05e8 \u05de\u05d5\u05db\u05df! [\u05dc\u05d4\u05d5\u05e8\u05d3\u05ea \u05d4-PDF \ud83d\udcc4](' + rp.download_url + ')';
  if (wantEmail) ans += '\n\n(\u05e9\u05dc\u05d9\u05d7\u05d4 \u05d1\u05de\u05d9\u05d9\u05dc \u05d0\u05d9\u05e0\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05db\u05e8\u05d2\u05e2 \u2014 \u05d9\u05e9 \u05dc\u05d4\u05d2\u05d3\u05d9\u05e8 SMTP \u05d1-n8n.)';
  return [{ json: { answer: ans, download_url: rp.download_url } }];
}
return [{ json: { answer: '\u05d0\u05d9\u05e8\u05e2\u05d4 \u05ea\u05e7\u05dc\u05d4 \u05d1\u05d4\u05e4\u05e7\u05ea \u05d4-PDF. \u05e0\u05e1\u05d4/\u05d9 \u05e9\u05d5\u05d1.' } }];
